        paragraphs = listOf(
            StoryParagraph("The morning came, came as mornings always come, came as the morning of Billy's death, came as the morning of the execution, came as the morning that would end the story of the handsome sailor.", "صبح آمد، همان‌طور که صبح‌ها همیشه می‌آیند آمد، به‌عنوان صبح مرگ بیلی آمد، به‌عنوان صبح اعدام آمد، به‌عنوان صبحی که داستان دریانورد زیبا را پایان می‌داد آمد."),
            StoryParagraph("Billy was brought on deck, brought in chains, brought before the assembled crew, brought to the place of execution, brought to the yardarm from which he would hang, brought to his death.", "بیلی بر عرشه آورده شد، در زنجیر آورده شد، در برابر خدمه گرد آمده آورده شد، به محل اعدام آورده شد، به بازوی دکل که از آن آویزان می‌شد آورده شد، به مرگش آورده شد."),
