    private fun chapter6() = StoryChapter(
        number = 6, title = "The Meaning", titlePersian = "معنا",
        paragraphs = listOf(
            StoryParagraph("And so the story of Billy Budd came to its end, came to the end that had been inevitable from the beginning, came to the end that Melville had written and rewritten and left unfinished at his death, came to the end that would haunt readers for generations.", "و اینگونه داستان بیلی باد به پایانش رسید، به پایانی رسید که از آغاز ناگزیر بود، به پایانی رسید که ملویل نوشته و بازنویسی کرده و در مرگش ناتمام گذاشته بود، به پایانی رسید که نسل‌ها خوانندگان را تسخیر می‌کرد."),
            StoryParagraph("What did it mean? What was Melville trying to say? What was the point of this story of innocence destroyed, of goodness defeated, of beauty crushed by the machinery of law and order and duty?", "معنایش چه بود؟ ملویل می‌خواست چه بگوید؟ هدف این داستان معصومیت نابودشده، خوبی شکست‌خورده، زیبایی خردشده توسط ماشین قانون و نظم و وظیفه چه بود؟"),
            StoryParagraph("Some said it was a story about the conflict between natural law and civil law, between the law of the heart and the law of society, between what we know to be right and what we are told to be right.", "بعضی می‌گفتند داستانی درباره تعارض بین قانون طبیعی و قانون مدنی است، بین قانون قلب و قانون جامعه، بین آنچه می‌دانیم درست است و آنچه به ما می‌گویند درست است."),
            StoryParagraph("Some said it was a story about the problem of evil, about the mystery of why some men are good and some are evil, about the question of why God allows evil to exist, about the silence of the heavens in the face of human suffering.", "بعضی می‌گفتند داستانی درباره مسئله شرارت است، درباره راز اینکه چرا بعضی مردان خوب و بعضی شریرند، درباره پرسش اینکه چرا خدا اجازه می‌دهد شرارت وجود داشته باشد، درباره سکوت آسمان‌ها در برابر رنج بشری."),
            StoryParagraph("Some said it was a story about the individual against society, about the price of nonconformity, about what happens to those who cannot or will not fit into the systems that society imposes.", "بعضی می‌گفتند داستانی درباره فرد در برابر جامعه است، درباره بهای ناهمرنگی، درباره آنچه برای کسانی رخ می‌دهد که نمی‌توانند یا نمی‌خواهند در نظام‌هایی که جامعه تحمیل می‌کند جا بگیرند."),
            StoryParagraph("Some said it was a story about the sea, about the harsh world of ships and sailors, about the discipline that was necessary to keep a ship afloat and a crew alive, about the sacrifices that such discipline required.", "بعضی می‌گفتند داستانی درباره دریا است، درباره جهان سخت کشتی‌ها و ملوانان، درباره انضباطی که برای شناور نگه داشتن کشتی و زنده نگه داشتن خدمه لازم بود، درباره فداکاری‌هایی که چنین انضباطی می‌خواست."),
            StoryParagraph("Some said it was a story about Melville himself, about his own struggles with good and evil, about his own questions about God and justice and the meaning of existence, about his own darkness and his own light.", "بعضی می‌گفتند داستانی درباره خود ملویل است، درباره کشمکش‌های خودش با خوبی و بدی، درباره پرسش‌های خودش درباره خدا و عدالت و معنای هستی، درباره تاریکی خودش و نور خودش."),
            StoryParagraph("But perhaps it was all of these things, and perhaps it was none of them, and perhaps the point of the story was precisely that there was no point, that life was not a story with a clear meaning, that tragedy was not a lesson but simply a fact.", "اما شاید همه این‌ها بود و شاید هیچ‌کدام، و شاید هدف داستان دقیقاً این بود که هدفی نداشت، که زندگی داستانی با معنای روشن نبود، که تراژدی درسی نبود بلکه تنها واقعیتی بود."),
            StoryParagraph("For Billy died, and nothing was gained by his death, and Claggart died, and nothing was gained by his death, and Captain Vere lived, and nothing was gained by his living, and the ship sailed on, and the world continued, and nothing changed.", "زیرا بیلی مرد و هیچ چیز از مرگش به دست نیامد، و کلاگارت مرد و هیچ چیز از مرگش به دست نیامد، و ناخدا ویر زیست و هیچ چیز از زندگی‌اش به دست نیامد، و کشتی به بادبانی ادامه داد و جهان ادامه یافت و هیچ چیز تغییر نکرد."),
            StoryParagraph("And yet, something did change, changed in the men who had witnessed the execution, changed in the readers who would hear the story, changed in all of us who had been touched by the tale of the handsome sailor.", "و با این حال، چیزی تغییر کرد، در مردانی که شاهد اعدام بودند تغییر کرد، در خوانندگانی که داستان را می‌شنیدند تغییر کرد، در همه ما که تحت تأثیر حکایت دریانورد زیبا قرار گرفته بودیم تغییر کرد."),
            StoryParagraph("For we had seen innocence, and we had seen evil, and we had seen the conflict between them, and we had seen the outcome, and we had been forced to confront the question that Billy's story posed: what would we have done?", "زیرا معصومیت را دیده بودیم و شرارت را دیده بودیم و تعارض میانشان را دیده بودیم و نتیجه را دیده بودیم و مجبور شده بودیم با پرسشی که داستان بیلی مطرح می‌کرد روبرو شویم: ما چه می‌کردیم؟"),
            StoryParagraph("Would we have condemned Billy, as Captain Vere did? Would we have shown mercy, as the officers wished? Would we have found a third way, a way that neither the law nor the heart could provide?", "آیا بیلی را محکوم می‌کردیم، همان‌طور که ناخدا ویر کرد؟ آیا رحم نشان می‌دادیم، همان‌طور که افسران می‌خواستند؟ آیا راه سومی می‌یافتیم، راهی که نه قانون و نه قلب می‌توانست فراهم کند؟"),
            StoryParagraph("And if we did not know the answer to that question, then perhaps that was the point, perhaps the story was meant to leave us uncertain, meant to make us question our own values, meant to force us to think about what we truly believed.", "و اگر پاسخ آن پرسش را نمی‌دانستیم، شاید همان هدف بود، شاید داستان مقصودش این بود که ما را نامطمئن بگذارد، ما را وادار کند ارزش‌های خودمان را زیر سؤال ببریم، ما را وادار کند درباره آنچه واقعاً باور داریم فکر کنیم."),
            StoryParagraph("For Billy Budd is not a story that provides answers, but a story that raises questions, not a story that comforts, but a story that disturbs, not a story that resolves, but a story that troubles.", "زیرا بیلی باد داستانی نیست که پاسخ‌ها را فراهم کند، بلکه داستانی است که پرسش‌ها را مطرح می‌کند، داستانی نیست که تسلی دهد، بلکه داستانی است که ناراحت می‌کند، داستانی نیست که حل کند، بلکه داستانی است که مشکل ایجاد می‌کند."),
            StoryParagraph("And that, perhaps, is its greatest strength, that it refuses to provide easy comfort, that it refuses to resolve its contradictions, that it refuses to let us off the hook.", "و این، شاید، بزرگ‌ترین قوتش است، اینکه از ارائه تسلی آسان امتناع می‌کند، از حل تناقضاتش امتناع می‌کند، از رها کردن ما از قلاب امتناع می‌کند."),
            StoryParagraph("For the questions that Billy Budd raises are the questions that every human being must face, the questions about good and evil, about justice and mercy, about law and love, about what it means to be human in a world that is not always humane.", "زیرا پرسش‌هایی که بیلی باد مطرح می‌کند پرسش‌هایی هستند که هر انسانی باید با آن‌ها روبرو شود، پرسش‌هایی درباره خوبی و بدی، درباره عدالت و رحم، درباره قانون و عشق، درباره معنای انسان بودن در جهانی که همیشه انسانی نیست."),
            StoryParagraph("And so the story ended, ended with the death of Billy Budd, ended with the burden of Captain Vere, ended with the silence of the crew, ended with the questions that remained unanswered and perhaps unanswerable.", "و اینگونه داستان تمام شد، با مرگ بیلی باد تمام شد، با بار ناخدا ویر تمام شد، با سکوت خدمه تمام شد، با پرسش‌هایی که بی‌پاسخ و شاید بی‌پاسخ‌ماندنی بودند تمام شد."),
            StoryParagraph("The end.", "پایان."),
            StoryParagraph("But the questions remain.", "اما پرسش‌ها باقی می‌مانند."),
            StoryParagraph("And so ended the sixth and final part of the story of Billy Budd, with the meaning of his life, with the meaning of his death, with the questions that would haunt readers forever.", "و اینگونه بخش ششم و آخرین داستان بیلی باد با معنای زندگی‌اش، با معنای مرگش، با پرسش‌هایی که برای همیشه خوانندگان را تسخیر می‌کردند به پایان رسید."),
            StoryParagraph("For Billy Budd was not merely a character in a story, not merely a handsome sailor who died on a British warship, but a symbol, a symbol of innocence in a world of corruption, a symbol of beauty in a world of ugliness, a symbol of good in a world of evil.", "زیرا بیلی باد تنها شخصیتی در داستان نبود، تنها دریانورد زیبایی نبود که در کشتی جنگی بریتانیایی مرد، بلکه نمادی بود، نمادی از معصومیت در جهانی از فساد، نمادی از زیبایی در جهانی از زشتی، نمادی از خوبی در جهانی از شرارت."),
            StoryParagraph("And his story, told and retold for generations, would continue to raise questions, continue to trouble readers, continue to remind us of the fragility of innocence and the cost of duty and the mystery of evil.", "و داستانش، که نسل‌ها تعریف و بازتعریف می‌شد، به مطرح کردن پرسش‌ها ادامه می‌داد، به ناراحت کردن خوانندگان ادامه می‌داد، به یادآوری شکنندگی معصومیت و بهای وظیفه و راز شرارت ادامه می‌داد."),
            StoryParagraph("And so the story of Billy Budd ended, as all great stories must end, not with an answer but with a question, not with a resolution but with a challenge, not with a comfort but with a disturbance.", "و اینگونه داستان بیلی باد به پایان رسید، همان‌طور که همه داستان‌های بزرگ باید تمام شوند، نه با پاسخ بلکه با پرسشی، نه با حل و فصل بلکه با چالشی، نه با تسلی بلکه با ناراحتی."),
            StoryParagraph("And so ended the story of Billy Budd, with the handsome sailor dead, with the questions asked, with the world changed, with nothing ever to be the same again.", "و اینگونه داستان بیلی باد با دریانورد زیبا مرده، با پرسش‌های پرسیده شده، با جهان تغییر یافته، با هیچ چیز که هرگز دوباره همان نخواهد بود، به پایان رسید."),
            StoryParagraph("The end.", "پایان."),
            StoryParagraph("But the questions remain.", "اما پرسش‌ها باقی می‌مانند.")
        )
    )
}